# =====================================================================
# DATA LOADING
# =====================================================================

def find_csv_path(filename: str):
    """
    Search common local locations for Customer_Churn_Predictions.csv.
    """

    here = os.path.dirname(os.path.abspath(__file__))

    candidates = [
        os.path.join(here, filename),
        os.path.join(here, "data", filename),
        os.path.join(here, "dataset", filename),
        os.path.join(here, "datasets", filename),
        os.path.join(here, "..", filename),
        os.path.join(
            here,
            "..",
            "Churn-Dataset-With-Geo-Loc-Analysis",
            filename,
        ),
        os.path.join(os.getcwd(), filename),
        filename,
    ]

    for candidate in candidates:
        candidate = os.path.normpath(candidate)
        if os.path.isfile(candidate):
            return candidate

    return None


@st.cache_data(show_spinner=False)
def load_data(csv_path: str) -> pd.DataFrame:
    """
    Load the real CSV and clean column names.
    """

    data = pd.read_csv(csv_path)

    if data.empty:
        raise ValueError("Customer_Churn_Predictions.csv is empty.")

    data.columns = [str(column).strip() for column in data.columns]

    return data


