# =====================================================================
# PLOTLY STYLE
# =====================================================================

def style_fig(fig: go.Figure, height: int = 300, show_legend: bool = False):
    """
    Apply the common dashboard Plotly style.
    """

    fig.update_layout(
        paper_bgcolor="rgba(0,0,0,0)",
        plot_bgcolor="rgba(0,0,0,0)",
        font=dict(color=TEXT, family="Arial, sans-serif", size=11),
        margin=dict(l=8, r=8, t=8, b=8),
        height=height,
        showlegend=show_legend,
        hovermode="closest",
        uirevision="telecom-churn-dashboard",
        transition={"duration": 0},
        legend=dict(
            orientation="h",
            yanchor="bottom",
            y=1.0,
            x=0,
            font=dict(size=10, color=TEXT),
        ),
    )

    fig.update_xaxes(
        gridcolor=GRID,
        zerolinecolor=GRID,
        linecolor=GRID,
        tickfont=dict(color=SUBTEXT, size=10),
        title_font=dict(color=SUBTEXT, size=10),
    )

    fig.update_yaxes(
        gridcolor=GRID,
        zerolinecolor=GRID,
        linecolor=GRID,
        tickfont=dict(color=SUBTEXT, size=10),
        title_font=dict(color=SUBTEXT, size=10),
    )

    return fig


# =====================================================================
# HTML HELPERS
# =====================================================================

def kpi_card(icon, value, label, color_1, color_2) -> str:
    return f"""
    <div class="kpi-card" style="background: linear-gradient(135deg, {color_1}, {color_2});">
        <div class="kpi-row">
            <div class="kpi-icon">{icon}</div>
            <div>
                <div class="kpi-value">{value}</div>
                <div class="kpi-label">{label}</div>
            </div>
        </div>
    </div>
    """


def gender_icon_data_uri() -> str:
    """
    Returns the exact reference male/female icon (embedded as base64)
    to be placed at the centre of the donut chart.
    """

    return GENDER_ICON_IMAGE_DATA_URI


def section_banner(text, color) -> str:
    return f"""
    <div class="section-banner" style="background:{color};">
        {text}
    </div>
    """


def vertical_label(text, css_class="") -> str:
    return f"""
    <div class="vertical-label {css_class}">
        <span>{text}</span>
    </div>
    """


