        _tenure_num = (
            pd.to_numeric(filtered_df[TENURE_COL], errors="coerce")
            .fillna(0)
            .astype(int)
        )

        _tenure_quarter = ((_tenure_num.clip(lower=1) - 1) % 12) // 3 + 1

        filtered_df = filtered_df[_tenure_quarter == _q_num]

